#include <bits/stdc++.h>
using namespace std;

using ll =  long long;

int main() {
	
	
	ll t; cin >> t;
	
	while(t--){
	    
	   ll n; cin >> n;
	   
	   vector<pair<ll,ll>> v1, v2;
	   
	   for(ll i =0; i < n; i++){
	       ll x, y; cin >> x >> y;
	       
	       v1.push_back({x,y});
	       v2.push_back({y, x});
	   }
	   
	   sort(v1.begin(), v1.end());
	   sort(v2.begin(), v2.end());
	   
	   ll x = 0, y = 0, xb = 0, yb = 0;
	   for(ll i = 1; i < n; i++){
	       ll a = v1[i].first, b = v1[i].second, c = v1[i-1].first, d = v1[i-1].second;
	       if(a  == c){
	           x = 1;
	           break;
	       }
	       else if(b < d){
	           xb+=1;
	       }
	   }
	   
	   for(ll i = 1; i < n; i++){
	       ll a = v2[i].first, b = v2[i].second, c = v2[i-1].first, d = v2[i-1].second;
	       
	       if(a == c) {
	           y = 1; 
	           break;
	       }
	       else if( b < d) yb++;
	   }
	   
	   if(x || y) cout << "NO\n";
	   else if( min(xb, yb) > 1) cout << "NO\n";
	   else cout << "YES\n";
	    
	}

}
